        '<div class="strong" style="margin:16px 0 8px">Recent</div>' + table(['When', 'Partner', 'Channel', 'Title', 'Email'], d.recent.map(function (n) { return '<tr><td class="small">' + dt(n.at) + '</td><td class="mono">' + esc(n.partner) + '</td><td>' + esc(n.channel) + '</td><td>' + esc(n.title) + '</td><td>' + esc(n.email_status) + '</td></tr>'; }), 'Nothing sent yet.');
      el.querySelectorAll('[data-t]').forEach(function (b) { b.onclick = function () { var t = d.templates.filter(function (x) { return x.key === b.dataset.t; })[0]; ctx.modal('<h2>' + esc(t.key) + '</h2><p class="muted small" style="margin:0">Variables like {{name}}, {{code}}, {{status}}, {{amount}}, {{note}} are replaced when sent.</p>' + field('t-sub', 'Subject / title', t.subject) + area('t-body', 'Body', t.body, 7) + '<label class="row" style="gap:6px"><input type="checkbox" id="t-on" style="width:auto"' + (t.active ? ' checked' : '') + '> Active</label><div class="row" style="justify-content:flex-end"><button class="btn" data-x>Cancel</button><button class="btn pri" data-s>Save</button></div>', function (m, c) { m.querySelector('[data-x]').onclick = c; m.querySelector('[data-s]').onclick = function () { act(m, 'admin_template_save', { p_key: t.key, p_subject: val(m, 't-sub'), p_body: m.querySelector('#t-body').value, p_active: val(m, 't-on') }, function () { c(); S.notifications(el); }, 'Saved'); }; }); }; });
