        table(['Category', 'Reference', 'Scope', 'Approved by', 'Approved on', 'Valid until', 'Recorded by', 'Status', ''], d.approvals.map(function (r) { return '<tr><td>' + esc(catName(a[1], r.category_key)) + '</td><td class="strong">' + esc(r.reference) + (r.document_url ? ' <a href="' + esc(r.document_url) + '" target="_blank" rel="noopener">doc</a>' : '') + '</td><td class="small">' + esc(r.scope) + '</td><td>' + esc(r.approved_by_name) + '</td><td>' + esc(r.approved_on) + '</td><td>' + esc(r.valid_until || '—') + '</td><td class="small">' + esc(r.recorded_by) + '</td><td>' + (r.revoked_at ? chip('rejected').replace('rejected', 'revoked') : chip('active')) + '</td><td>' + (can('compliance.manage') && !r.revoked_at ? btn('Revoke', 'data-v="' + r.id + '"', 'danger') : '') + '</td></tr>'; }), 'No approvals recorded. Every category’s commission is therefore off.');
      var nb = el.querySelector('#l-new'); if (nb) nb.onclick = function () { ctx.modal('<h2>Record legal approval</h2><label class="f">Category<select id="l-cat">' + a[1].map(function (c) { return '<option value="' + esc(c.key) + '">' + esc(c.name) + '</option>'; }).join('') + '</select></label>' + field('l-ref', 'Reference (opinion no. / date / firm)') + area('l-scope', 'Exact activity and compensation approved', '', 3) + field('l-by', 'Approved by (counsel / firm)') + '<div class="two">' + field('l-on', 'Approved on', '', 'date') + field('l-until', 'Valid until (optional)', '', 'date') + '</div>' + field('l-url', 'Link to the opinion (optional, https://)') + '<div class="row" style="justify-content:flex-end"><button class="btn" data-x>Cancel</button><button class="btn pri" data-s>Record</button></div>', function (m, c) { m.querySelector('[data-x]').onclick = c; m.querySelector('[data-s]').onclick = function () { act(m, 'admin_compliance_record', { p: { category_key: val(m, 'l-cat'), reference: val(m, 'l-ref'), scope: m.querySelector('#l-scope').value, approved_by_name: val(m, 'l-by'), approved_on: val(m, 'l-on'), valid_until: val(m, 'l-until'), document_url: val(m, 'l-url') } }, function () { c(); S.compliance(el); }, 'Recorded'); }; }); };
      el.querySelectorAll('[data-v]').forEach(function (b) { b.onclick = function () { if (window.confirm('Revoke this approval? If it is the last valid one, commission is switched off for the category.')) act(el, 'admin_compliance_revoke', { p_id: b.dataset.v }, function () { cache.cats = null; S.compliance(el); }); }; });
